import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>AVIF 是网上最新的图片格式，也是大多数软件打不开的格式。从现代网站上下载一张漂亮的图片，你的看图软件、编辑器或上传表单却拒绝了它。</p>\n<p>把 AVIF 转成 JPG 就能解决这个问题。转出来的文件到处都能打开，从用了十年的旧笔记本到政务网站都一样，而且整个转换只要几秒钟。</p>\n<p>这篇指南会讲清楚 AVIF 是什么、它为什么存在，以及怎么干净地转换它。</p>\n<h2 id=\"what-is-avif\">什么是 AVIF？</h2>\n<p>AVIF 是 AV1 图片文件格式（AV1 Image File Format）的缩写。它基于 AV1 视频编码器，也就是现代视频流用的技术，改成存放静态图片。</p>\n<p>这个格式压缩照片的效率极高。同样视觉画质下，AVIF 图片通常比 JPG 小 30% 到 50%，网站纷纷采用它就是这个原因。</p>\n<p>AVIF 支持高动态范围、宽色域、透明度，甚至动画。单从技术上说，它是当今能力最强的图片格式。</p>\n<p>这个格式开放且免版税，由开放媒体联盟开发。开放性让它很快在浏览器和网站上传播开来。</p>\n<h2 id=\"why-websites-use-avif\">现代网站为什么用 AVIF？</h2>\n<p>网站用 AVIF，是因为它能让页面加载更快。照片小一半，加载时间也少一半，访客体验和搜索排名都会变好。</p>\n<p>现代浏览器原生支持 AVIF。Chrome、Edge、Firefox 和 Safari 都能显示它，大多数访客看图片没有任何问题。</p>\n<p>内容分发网络会自动把图片转成 AVIF。网站可能给现代浏览器提供 AVIF，给老浏览器提供 JPG，站长自己什么都不用做。</p>\n<p>你总在下载 AVIF 文件，就是这种自动转换的结果。格式是网站选的，不是你选的，你的电脑只能处理这个结果。</p>\n<h2 id=\"why-apps-reject-avif\">为什么软件和表单拒绝 AVIF？</h2>\n<p>AVIF 还很新，很多系统在它出现之前就建好了。上传表单、打印机和老软件只认 JPG 和 PNG，AVIF 不在允许列表里。</p>\n<p>桌面修图软件跟进得很慢。Photoshop 现在支持 AVIF 了，但很多老编辑器还不支持，浏览器里打得开的文件，编辑器里可能打不开。</p>\n<p>操作系统也是新旧两样。新版 Windows、macOS 和安卓能处理 AVIF，老版本却只显示一个破损图标。</p>\n<p>转成 JPG 就能彻底消除这些不确定性。JPG 用了三十年，到处都认，这三十年里建起来的系统没有一个会拒绝它。</p>\n<h2 id=\"how-decoding-works\">浏览器里 AVIF 是怎么解码的？</h2>\n<p>现代浏览器能原生解码 AVIF，转换器直接用浏览器自己的解码器来读取文件。不用额外插件，也不用下载东西。</p>\n<p>解码后的像素画到画布上，再导出为标准的 JPG、PNG 或 WebP。结果是一张普通的、任何软件都能打开的图片文件。</p>\n<p>浏览器解码不了 AVIF 时，转换会失败并给出明确的提示。更新浏览器通常就能解决，因为 AVIF 支持是在较新的版本里才加上的。</p>\n<p>转换完全在你的设备上进行。下载的图片永远不会离开你的电脑，私人文件和客户工作也不用担心外泄。</p>\n<h2 id=\"quality-settings\">实用的画质设置</h2>\n<p>大多数 AVIF 照片用 85% 的 JPG 画质最合适。照片看着干净，文件大小合理，原来的损失肉眼看不见。</p>\n<p>要拿去打印的图片，用 90% 或更高的画质。打印会放大屏幕上看不出的瑕疵，单张重要图片多占一点空间完全值得。</p>\n<p>要发给有大小限制的表单时，从 85% 开始逐步往下调。每调一步看一下大小，文件刚好符合要求就停下。</p>\n<p>AVIF 照片常常画质非常高，所以转换时很耐折腾。85% 的 JPG 在正常观看尺寸下，通常看起来和 AVIF 一模一样。</p>\n<h2 id=\"file-size-after\">为什么转出来的 JPG 更大？</h2>\n<p>转出来的 JPG 几乎总是比原来的 AVIF 大，常常大一倍。很多人第一次看到会吃惊，但这完全正常。</p>\n<p>AVIF 比 JPG 高效得多。从新格式回到老格式要多占空间，因为 JPG 没法用更少的字节装下同样的细节。</p>\n<p>JPG 并没有变差。它装的是同一张图，只是存得没那么高效。多出来的体积，就是换取通用兼容性的代价。</p>\n<p>如果体积实在是个问题，把画质降到 80%。这一步常常能让文件小一半，肉眼却几乎看不出变化。</p>\n<h2 id=\"transparency-handling\">AVIF 转换中的透明度</h2>\n<p>AVIF 和 PNG、WebP 一样支持透明度。带透明区域的 AVIF 变成 JPG 时，这些区域必须用一个纯色填充。</p>\n<p>默认白色，适合大多数文档和网页。转到白色上的标志，放在白底页面或 Word 文档里看起来很自然。</p>\n<p>深色设计就选黑色，或者直接输入十六进制颜色码，精确匹配某个网站的背景色。背景对上了，标志看起来就像本来长在那里一样。</p>\n<p>要保留透明度就转成 PNG。<a href=\"/zh/zhuanhuan-tupian/\">图片转换器</a>能把 AVIF 输出为 PNG，透明通道得以保留。</p>\n<h2 id=\"hdr-and-colour\">HDR 与宽色域照片</h2>\n<p>AVIF 支持高动态范围和宽色域，能捕捉比标准格式更亮的高光和更丰富的颜色。这些功能是这个格式看起来这么好的原因之一。</p>\n<p>转成 JPG 会把 HDR 数据压平成标准颜色。图片依然好看，但最亮的高光和最饱和的颜色可能看起来稍微暗淡一点。</p>\n<p>大多数照片的这种变化很细微。只有高光特别亮或颜色特别浓烈的图片，转换后才能看出差别。</p>\n<p>对颜色敏感的工作，转换后把 JPG 和 AVIF 仔细对比一下。差别很重要的话，就留着 AVIF 做母版，只在兼容性要求的地方用 JPG。</p>\n<h2 id=\"batch-converting\">批量转换下载的 AVIF</h2>\n<p>下载的几个 AVIF 文件可以一次批量转换。每个文件独立转换，最后打包进一个 ZIP 里。</p>\n<p>单个文件最大支持 25MB，高清下载图和相机直出的照片都不用提前处理，直接就能转。</p>\n<p>整批用同一个画质和填充色设置。同一份文档或同一个项目里的图片，保持一致才专业。</p>\n<p>批量运行时留意错误提示。浏览器解码不了的文件会显示警告，更新浏览器通常就能解决。</p>\n<h2 id=\"checking-quality\">下载前检查画质</h2>\n<p>点任意卡片上的“对比”，就能并排看到 AVIF 和 JPG。拖动分隔线，检查人脸、文字和细节。</p>\n<p>先检查颜色，因为宽色域的 AVIF 照片转换时可能轻微偏移。快速对比一下，就能看出这张图的偏移是否重要。</p>\n<p>如果结果看着发软，把画质提高 5 个点再转一次。原 AVIF 还留在队列里，不用重新上传。</p>\n<p>批量转换时，抽查三四张有代表性的文件就行，不用每张都看。设置相同，抽查的几张没问题，其余的也不会有问题。</p>\n<h2 id=\"avif-vs-jpg-decision\">什么时候留着 AVIF</h2>\n<p>图片放在现代网站上时，留着 AVIF。文件更小，页面加载更快，所有现代浏览器都能显示。</p>\n<p>从网站上下载图片时，把 AVIF 留着做母版。它是你手里画质最好的版本，需要别的格式时随时可以再转。</p>\n<p>目的地是表单、打印机、邮件或老软件时，转成 JPG。那里兼容性比体积更重要，JPG 到处都能打开。</p>\n<p>别把整个 AVIF 收藏都转成 JPG 以防万一。那样只会让存储翻倍，却没有任何好处，因为大多数图片永远不会离开现代网页。</p>\n<h2 id=\"common-problems\">常见问题与解决办法</h2>\n<p>转换失败了，可能是浏览器太老，解码不了 AVIF。更新到最新版 Chrome、Edge、Firefox 或 Safari，再试一次。</p>\n<p>JPG 看着发灰，可能是 HDR 或宽色域颜色在转换时偏移了。在任何修图软件里稍微调一下饱和度，就能恢复那种鲜艳感。</p>\n<p>透明 AVIF 转成的 JPG 里出现黑框，说明填充色是黑色或者没设置。改成白色或你的页面颜色，再转一次就行。</p>\n<p>JPG 比 AVIF 大得多，这是正常的。AVIF 更高效，大一点的 JPG 就是换取通用格式的代价。</p>\n<h2 id=\"avif-from-news-sites\">新闻网站上的 AVIF 图片</h2>\n<p>新闻网站为了让页面加载更快，把图片以 AVIF 提供，所以从新闻文章里保存下来的照片常常是 AVIF 文件。浏览器里打得开，修图软件里却打不开。</p>\n<p>在别处使用之前，先把 AVIF 转成 JPG。JPG 在 Word、Photoshop 和其他所有软件里都能打开，而 AVIF 有一半软件都认不了。</p>\n<p>转换后检查一下画质。新闻照片常常已经被网站压缩过一次，转出来的 JPG 可能偏软，再提高画质也找不回丢掉的细节。</p>\n<p>打算长期保存的照片，也留一份 AVIF 原件。它是你从网站上能拿到的最好画质版本，以后需要别的格式还能再转。</p>\n<p>使用时要尊重照片的版权。新闻照片属于创作者或通讯社，转个格式并不会改变所有权。</p>\n<h2 id=\"avif-for-work\">工作中的 AVIF 图片</h2>\n<p>工作文档经常要用到网上下载的图片，而这些图片通常是 AVIF。直接粘贴到 Word 或 PowerPoint 里可能失败，因为老版 Office 不支持 AVIF。</p>\n<p>放进文档之前，先把 AVIF 转成 JPG。JPG 在所有版本的 Office 里都能干净地嵌入，文档在任何同事的电脑上打开都正常。</p>\n<p>一份报告里有很多网络图片时，先把整批转好再开始写文档。这样就不会辛苦几小时后才发现一半图片都是坏的。</p>\n<p>转换后看一眼文件大小。二十张 2MB 的 JPG 放进报告就是 40MB，可能超出邮件附件上限，报告要发邮件的话记得先压缩图片。</p>\n<p>要打印的报告，画质保持在 90% 以上。打印会放大屏幕上看不出的瑕疵，高画质 JPG 是印在纸上最稳妥的选择。</p>\n<h2 id=\"avif-for-printing\">要打印的 AVIF 图片</h2>\n<p>打印店只认 JPG 或 PNG，拿着 AVIF 去可能被系统拒绝。下单打印之前先转成 JPG，再确认一下打印店的具体要求。</p>\n<p>打印用的图片，画质保持在 90% 以上。6 寸照片需要每一个像素的细节，低画质 JPG 的瑕疵印在纸上会很明显。</p>\n<p>打印前先看尺寸。800 像素宽的图片印 3 寸很清晰，印 10 寸就糊了，打印尺寸要和像素数匹配。</p>\n<p>要印大幅的，就用手头分辨率最高的原图。网上下载的 AVIF 通常比较小，再怎么转换也变不出大幅打印需要的像素。</p>\n<p>重要的照片先印一张小样试试。一张小样就能确认颜色和清晰度，再决定要不要下大单或印画布。</p>\n<h2 id=\"avif-for-social-media\">社交媒体上的 AVIF 图片</h2>\n<p>社交平台以 AVIF 提供图片，也接受 AVIF 上传。用 AVIF 发照片加载更快，不过平台反正会把它转成自己的格式。</p>\n<p>发照片帖子时，上传高质量的 JPG 更好。平台反正要压缩一次，JPG 输入在所有平台上都是兼容性最好的起点。</p>\n<p>带文字的配图，上传 PNG 或高质量 WebP。文字在平台压缩后依然更锐利，公告图尤其需要这一点。</p>\n<p>上传前先查平台推荐的尺寸。Instagram、Facebook 和 X 各有理想尺寸，尺寸合适比格式更重要。</p>\n<p>上传后下载平台上的版本检查一下。快速看一眼发布后的帖子，就能确认图片在平台处理后是否完好。</p>\n<h2 id=\"keeping-avif-originals\">转换后留好 AVIF 原件</h2>\n<p>转换出来的 JPG 只是用来交付的副本，不是母版。AVIF 原件才是你手里画质最好的版本，值得妥善保存。</p>\n<p>把 AVIF 原件按来源放进文件夹，比如起名叫“网站下载”。文件夹名字清楚，以后要用的时候一下就能找到。</p>\n<p>转换完别急着删原件。JPG 永远变不回完美的 AVIF，原件就是你的保险，万一以后需要别的格式还能再转。</p>\n<p>原件最好备份两处。本地硬盘加一份云备份，能防硬件损坏、被盗和误删。</p>\n<p>每隔一两年检查一次原件。格式一直在变，AVIF 存档可能需要在旧格式难打开之前，迁移到更新的格式上。</p>\n<p>准备好转换了吗？打开 <a href=\"/zh/avif-zhuan-jpg/\">AVIF 转 JPG 工具</a>，把文件拖进去就行。具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-avif-zhuan-huan-wei-jpg/\">如何把 AVIF 转换成 JPG</a>，正面对照可以看<a href=\"/zh/blog/avif-vs-jpg-duibi/\">AVIF vs JPG：新一代格式与通用格式对比</a>。如果要保留透明度，<a href=\"/zh/zhuanhuan-tupian/\">图片转换器</a>可以把 AVIF 转成 PNG。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"AVIF 是什么？为什么有些软件打不开它？","answer":"AVIF 是基于 AV1 视频编码器的现代图片格式，压缩照片比 JPG 小 30% 到 50%。很多软件和表单在 AVIF 出现之前就建好了，只接受 JPG 和 PNG。转成 JPG，图片就到处能打开了。"},{"question":"哪些浏览器能解码 AVIF 来做转换？","answer":"新版 Chrome、Edge、Firefox 和 Safari 都能原生解码 AVIF，转换器用的就是浏览器的解码能力。浏览器太老了，转换会失败并给出明确提示，更新浏览器通常就能解决。解码完全在你的设备上进行。"},{"question":"AVIF 转 JPG 会损失画质吗？","answer":"会损失一点，因为 JPG 比 AVIF 更有损，不过画质设到 85%，正常观看时看不出来。照片保持完整分辨率，屏幕上看起来和原来一样。只有 HDR 高光和特别饱和的颜色，转换时可能轻微偏移。"},{"question":"透明 AVIF 的透明部分转成 JPG 会变黑吗？","answer":"只有填充色是黑色或没设置时才会。JPG 存不了透明度，透明区域会被你选的填充色填满。大多数情况选白色，或者输入十六进制颜色码匹配特定背景，下载前检查一下结果。"},{"question":"转换接受的 AVIF 文件最大是多大？","answer":"每个 AVIF 文件最大 25MB，高清下载图和相机直出的照片都能覆盖。解码在你的设备上运行，大文件按本地速度处理，不用等上传。"},{"question":"为什么转出来的 JPG 有时比 AVIF 大？","answer":"AVIF 比 JPG 高效得多，同一张图片存成 JPG 需要更多字节。画面本身没变，只是不如原来存得高效。多出来的体积就是换取通用兼容性的代价。把画质降到 80%，文件常常能再小一半。"}];
